// Zen R4 bring-up: exercise every header-exposed FPGA GPIO.
// Generated by gen_zen.py -- do not edit by hand.
//
// Patterns cycle automatically:
//   0  walking one    -- identify each pin individually
//   1  walking zero   -- same, inverted (catches stuck-high)
//   2  even/odd split -- catches shorts between adjacent pins
//   3  all blink      -- quick visual / current draw check
//
// SAFE_MODE=1 holds the config-strap / dual-function pins static low.

`default_nettype none

module blink #(
    parameter SAFE_MODE = 1,
    parameter CLK_HZ    = 50000000,
    parameter STEP_HZ   = 5
) (
    input  wire clk,
    output wire led,        // F3  IOL_11
    output wire led2,       // G1  IOL_12
    output wire led3,       // F1  IOL_13
    output wire led4,       // E2  IOL_14
    output wire led5,       // E1  IOL_15
    output wire led6,       // C2  IOL_16
    output wire led7,       // D2  IOL_17
    output wire led8,       // E3  IOL_18
